internal enum class PlatformBrand(val displayName: String) {
    OPENAI_CODEX("OpenAI Codex"),
    DEEPSEEK("DeepSeek"),
    SILICON_FLOW("SiliconFlow"),
    XIAOMI_MIMO("Xiaomi MIMO"),
    VOLCENGINE("火山引擎"),
    OPENCODE("OpenCode"),
    KIMI("Kimi"),
    GLM("GLM"),
    CUSTOM_ENDPOINT("自定义接口"),
}

internal fun platformBrand(authMode: BalanceAuthMode): PlatformBrand = when (authMode) {
    BalanceAuthMode.DEEPSEEK_API_KEY, BalanceAuthMode.DEEPSEEK_CONSOLE -> PlatformBrand.DEEPSEEK
    BalanceAuthMode.API_KEY, BalanceAuthMode.SILICONFLOW_CONSOLE -> PlatformBrand.SILICON_FLOW
    BalanceAuthMode.MIMO_BALANCE, BalanceAuthMode.MIMO_TOKEN_PLAN -> PlatformBrand.XIAOMI_MIMO
    BalanceAuthMode.VOLCENGINE_BALANCE,
    BalanceAuthMode.VOLCENGINE_CODING_PLAN,
    BalanceAuthMode.VOLCENGINE_AGENT_PLAN -> PlatformBrand.VOLCENGINE
    BalanceAuthMode.OPENCODE_ZEN, BalanceAuthMode.OPENCODE_GO -> PlatformBrand.OPENCODE
    BalanceAuthMode.KIMI, BalanceAuthMode.KIMI_BALANCE -> PlatformBrand.KIMI
    BalanceAuthMode.GLM_BALANCE, BalanceAuthMode.GLM_CODING_PLAN -> PlatformBrand.GLM
    BalanceAuthMode.EMAIL_PASSWORD -> PlatformBrand.CUSTOM_ENDPOINT
}

/** 新建服务时预填品牌与服务类型，用户仍可在编辑器中自行修改。 */
internal fun defaultBalanceServiceName(authMode: BalanceAuthMode): String = when (authMode) {
    BalanceAuthMode.EMAIL_PASSWORD -> ""
    BalanceAuthMode.MIMO_TOKEN_PLAN -> "Xiaomi MIMO Token Plan"
    BalanceAuthMode.VOLCENGINE_CODING_PLAN -> "火山引擎 Coding Plan"
    BalanceAuthMode.VOLCENGINE_AGENT_PLAN -> "火山引擎 Agent Plan"
    BalanceAuthMode.OPENCODE_ZEN -> "OpenCode Zen 账户余额"
    BalanceAuthMode.OPENCODE_GO -> "OpenCode Go 配额"
    BalanceAuthMode.KIMI,
    BalanceAuthMode.GLM_CODING_PLAN -> "${platformBrand(authMode).displayName} Coding Plan"
    else -> "${platformBrand(authMode).displayName} 账户余额"
}

internal object PlatformLogoBitmaps {
    private val openAi by lazy(LazyThreadSafetyMode.PUBLICATION) { decode(OPENAI, 0.86f) }
    private val deepSeek by lazy(LazyThreadSafetyMode.PUBLICATION) { decode(DEEPSEEK, 0.92f) }
    private val siliconFlow by lazy(LazyThreadSafetyMode.PUBLICATION) { decode(SILICON_FLOW, 0.90f) }
    private val xiaomiMimo by lazy(LazyThreadSafetyMode.PUBLICATION) { decode(XIAOMI_MIMO, 0.72f) }
    private val volcengine by lazy(LazyThreadSafetyMode.PUBLICATION) { decode(VOLCENGINE, 0.78f) }
    private val openCode by lazy(LazyThreadSafetyMode.PUBLICATION) { decode(OPENCODE, 0.82f) }
    private val kimi by lazy(LazyThreadSafetyMode.PUBLICATION) { decode(KIMI_OFFICIAL, 0.78f) }
    private val glm by lazy(LazyThreadSafetyMode.PUBLICATION) { decode(GLM, 0.78f) }

    fun get(brand: PlatformBrand): ImageBitmap? = when (brand) {
        PlatformBrand.OPENAI_CODEX -> openAi
        PlatformBrand.DEEPSEEK -> deepSeek
        PlatformBrand.SILICON_FLOW -> siliconFlow
        PlatformBrand.XIAOMI_MIMO -> xiaomiMimo
        PlatformBrand.VOLCENGINE -> volcengine
        PlatformBrand.OPENCODE -> openCode
        PlatformBrand.KIMI -> kimi
        PlatformBrand.GLM -> glm
        PlatformBrand.CUSTOM_ENDPOINT -> null
    }

    /**
     * 品牌原图的透明边距和内容占比不同。先裁掉透明边距，再按光学比例放回统一画布，
     * 这样列表使用相同 dp 尺寸时不会出现某个图标明显偏大或偏小。
     */
    private fun decode(encoded: String, opticalScale: Float): ImageBitmap? {
        val bytes = runCatching { Base64.decode(encoded, Base64.DEFAULT) }.getOrNull() ?: return null
        val source = BitmapFactory.decodeByteArray(bytes, 0, bytes.size) ?: return null
        val bounds = opaqueBounds(source)
        if (bounds.width() <= 0 || bounds.height() <= 0) {
            source.recycle()
            return null
        }
        val outputSize = 96
        val targetSize = outputSize * opticalScale.coerceIn(0.6f, 0.92f)
        val scale = minOf(targetSize / bounds.width(), targetSize / bounds.height())
        val drawWidth = bounds.width() * scale
        val drawHeight = bounds.height() * scale
        val destination = RectF(
            (outputSize - drawWidth) / 2f,
            (outputSize - drawHeight) / 2f,
            (outputSize + drawWidth) / 2f,
            (outputSize + drawHeight) / 2f,
        )
        val output = android.graphics.Bitmap.createBitmap(outputSize, outputSize, android.graphics.Bitmap.Config.ARGB_8888)
        Canvas(output).drawBitmap(source, bounds, destination, Paint(Paint.ANTI_ALIAS_FLAG or Paint.FILTER_BITMAP_FLAG))
        source.recycle()
        return output.asImageBitmap()
    }

    private fun opaqueBounds(bitmap: android.graphics.Bitmap): Rect {
        var left = bitmap.width
        var top = bitmap.height
        var right = -1
        var bottom = -1
        for (y in 0 until bitmap.height) {
            for (x in 0 until bitmap.width) {
                if ((bitmap.getPixel(x, y) ushr 24) > 12) {
                    left = minOf(left, x)
                    top = minOf(top, y)
                    right = maxOf(right, x)
                    bottom = maxOf(bottom, y)
                }
            }
        }
        return if (right >= left && bottom >= top) Rect(left, top, right + 1, bottom + 1) else Rect(0, 0, bitmap.width, bitmap.height)
    }

    // Kimi 官网 favicon 转换出的 PNG。保留在包内，运行时不会联网下载品牌资源。
    private const val KIMI_OFFICIAL = ""

    private const val OPENAI = ""
    private const val VOLCENGINE = ""
    private const val OPENCODE = "iVBORw0KGgoAAAANSUhEUgAAADAAAAAwCAYAAABXAvmHAAAAcklEQVR42u3Z0QmAIBQFUI0GUGqn3H+OwBHqowmkLIxz/wUP73E/NC4pHWHgTGHwAAAAAADcytx6YK+1+6XWnK0QAIAW6tgcTzaaFQIA0EJXtlJMAAAAAAAAAADg5cTWHxoPW1YIAODbFjIBAAAAgF8BTiDWDdFos1/3AAAAAElFTkSuQmCC"
    private const val KIMI = ""
    private const val GLM = ""
    private const val DEEPSEEK = ""
    private const val SILICON_FLOW = ""
    private const val XIAOMI_MIMO = ""
}
